function promotionContent(d) {
  if (typeof d.promoContent !== 'string') {
    const plan = d.promoPlan || d.answers?.[3] || d.notes?.[3] || '';
    d.promoContent = [plan, d.message && d.message !== plan ? 'Key message: ' + d.message : ''].filter(Boolean).join('\n\n');
  }
  return d.promoContent;
}
const musicGenres = {
  'Dance pop': 'Bright synths, energetic electronic drums and a memorable chorus.',
  'Pop': 'A clear melody, steady drums and bass, approachable vocals and chorus.',
  'Choir': 'Blended vocal harmonies, clear lyrics and an easy-to-sing chorus.',
  'Korean traditional fusion': 'Combine instruments such as gayageum and haegeum with contemporary rhythms and natural English phrasing.',
  'Acoustic': 'Warm acoustic guitar and piano, restrained percussion and intimate natural vocals.'
};
const videoAudiences = {
  'Match the service audience': 'Choose genders and age groups based on the actual intended users and service context.',
  'Women and men': 'Include women and men within the intended service audience, with appropriate ages.',
  'Male service users': 'Focus on male users in age groups relevant to the service.',
  'Female service users': 'Focus on female users in age groups relevant to the service.'
};
const videoDirections = {
  'Rhythmic ad': 'An upbeat policy advertisement with brisk cuts and user actions timed to music.',
  'Cinematic': 'Film-like views of service spaces and use, expressive lighting and natural transitions.',
  'Vlog': 'Follow users closely through a vivid, personal service experience.',
  'Documentary': 'Observational framing, natural actions and location sound. Do not imply a fictional scene is a real interview or proven outcome.',
  'Animation': 'Consistent character design, a coherent visual style and clear animated actions showing the service.'
};
function videoFields() {
  const d = draft();
  return `<label for="videoAudience">Service users</label><select id="videoAudience" data-field="videoAudience">${Object.keys(videoAudiences).map(x => `<option ${x === (d.videoAudience || 'Match the service audience') ? 'selected' : ''}>${x}</option>`).join('')}</select>${field('Additional service or usage details', 'videoServiceDetail', d.videoServiceDetail || '', true, 'Describe the service, situation or age group to emphasize. Leave blank to use the policy context.')}<div class="hint">3 distinct concepts · 3 separate 10-second videos<br>Each is a complete standalone advertisement. Copy each prompt separately to generate its video.</div>`;
}
function mediaBrief() {
  const d = draft(), t = topics[state.topic], detail = policyDetails[state.topic];
  return `[SEOUL POLICY COMMUNICATION BRIEF]
Vision: G3 Seoul Plan — A Global Leader in Quality of Life
Policy area: ${groups[t[1]][0]}
Workshop group: ${state.topic + 1}
Policy: ${t[0]}
Audience: ${d.audience || 'Seoul residents'}
Policy details and benefits (reference material):
${promotionContent(d) || [t[7], ...detail.measures, 'Potential benefits for residents: ' + detail.change].join('\n')}

[COMMON PRINCIPLES]
Use the supplied material to explain the policy and how it could improve daily life. Do not invent results, figures, budgets, dates, eligibility rules, testimonials, contact details or application links. Distinguish proposals and expected benefits from confirmed implementation and achieved results. Use clear English throughout, including dialogue, lyrics and text within images. Translate any user-provided material into English faithfully without adding facts. Use only material relevant to the selected policy; flag unrelated material in production notes.`;
}
function musicPrompt() {
  const d = draft(), genre = Object.hasOwn(musicGenres, d.creativeStyle) ? d.creativeStyle : 'Dance pop';
  return `${mediaBrief()}

[PROMOTIONAL SONG]
Selected genre: ${genre} — ${musicGenres[genre]}
Apply the selected genre to the rhythm, instrumentation and vocals. Do not switch genres.
Write complete, original English lyrics for a song of approximately 2 minutes (120 seconds). Use Intro → Verse 1 → Pre-Chorus → Chorus → Verse 2 → Bridge → Final Chorus → Outro. Include all repeated choruses in full. Naturally incorporate “Seoul, a city for a better life” into the chorus and convey the policy and its benefits. Do not imitate a specific artist or existing song.
Provide exactly one Markdown code block (text) containing both the music settings and full lyrics, ready to paste into Flow Music. Keep all material to copy inside that block.
Under [MUSIC SETTINGS], include title, genre, BPM, time signature, key, instrument roles, groove, vocals, harmonies, pronunciation, mood, arrangement, mixing and section durations totaling approximately 120 seconds.
Under [LYRICS], include the full finished English lyrics. Instruct the generator to sing only the lyrics, not settings or section headings. Duration is a target; do not invent service-specific syntax or features.`;
}
function videoPrompt() {
  const d = draft();
  const style = Object.hasOwn(videoDirections, d.creativeStyle) ? d.creativeStyle : 'Rhythmic ad';
  const audience = Object.hasOwn(videoAudiences, d.videoAudience) ? d.videoAudience : 'Match the service audience';
  return `${mediaBrief()}

[LANGUAGE]
Write the entire video production prompt in English, including concept titles, direction, camera work, lighting, sound, character descriptions, restrictions and spoken dialogue. Each code block must be ready to paste directly into a video generation tool.

[SERVICE USERS]
Composition: ${audience} — ${videoAudiences[audience]}
Additional request: ${d.videoServiceDetail || 'Suggest service situations and ages appropriate to the policy.'}
Identify the purpose, core service and actual intended users from the supplied material. Specify appropriate genders, ages and usage situations. A policy for young people should feature young people; elementary-school learning support should feature children and caregivers where relevant. Do not force every age group into every policy or assign roles through age or gender stereotypes. Casting choices are illustrative, not official eligibility criteria.
Keep the service space, delivery, user actions and benefits central. Avoid excessive focus on a single character’s appearance or personal backstory. Cast each video independently, maintaining character consistency within that video.

[DIRECTION AND THREE DISTINCT CONCEPTS]
Selected direction: ${style} — ${videoDirections[style]}
Create THREE SEPARATE 10-SECOND VIDEOS, each a complete standalone policy advertisement. Do not create a connected 30-second story, or divide an introduction, process and conclusion across three clips.
Keep the same policy facts, key message and selected direction across all three, but differentiate the concepts:
Video 1 — Everyday connection: Tell a compact story about a relevant daily situation, service use and the benefit to a resident.
Video 2 — Service experience: Use close views of service spaces, facilities, tools and concrete user actions to communicate how the service works and helps.
Video 3 — Key message: Use a striking visual composition, concise action and a short line of dialogue to communicate the policy’s central value. Show identifiable service details, not abstract atmosphere alone.
Differentiate situations, main visual elements, framing and communication methods; do not merely change people or colors. Each video must contain its own service introduction, user action, benefit and conclusion within one simple situation.
Give EACH video its own 0–10 second timeline: attract attention at 0–2 seconds, show the service at 2–7 seconds, and complete the benefit and message at 7–10 seconds. Do not rely on another video, matching action, a teaser or connecting edits. End each video naturally.
Do not invent procedures or functions. Identify proposed services as proposals. Avoid lengthy problem exposition and generic aerial footage. Use at most one short English sentence of dialogue per video, naturally speakable within 10 seconds and grounded in the supplied material.

[OUTPUT FORMAT]
Output exactly THREE independent Markdown code blocks (text), one prompt for each separately generated 10-second video in Flow AI. Put a video number and distinct concept title before each block.
Each block must work on its own in a fresh generation request. Repeat all essential context inside EACH block: policy name, supporting policy details, key message, audience, concept, selected direction, standalone 10-second duration, its own 0–10 second action timeline, framing, camera, lighting, sound, exact English dialogue and speaker, service and benefits, users’ ages, genders, roles, appearance, clothing and voices, opening and closing shots, and restrictions.
Do not omit settings by referring to the brief above, a previous clip or shared settings elsewhere. No cliffhangers or transitions into another video. Do not include subtitles, captions, on-screen text, logos or watermarks in the videos.
If the material is a proposal, add “Educational policy proposal — official implementation requires verification” in production notes only, not on screen. Use this note only when applicable. Do not add other code blocks.`;
}

const policyDetails=[{"purpose":"Help residents exercise consistently close to home without traveling long distances.","measures":["Expand Seoul fitness centers and mobile fitness services.","Extend Fun Stations using unused subway spaces into more districts.","Develop a health and vitality eco-platform linking forests, parks and waterfronts."],"change":"More opportunities to exercise near home or on the way back from work. Opening hours, ease of booking and accessibility matter as well as distance.","pages":"p. 3"},{"purpose":"Reduce everyday risks so residents can feel safer regardless of time or place.","measures":["Separate sidewalks from traffic lanes in school zones with frequent accidents.","Expand Seoul emergency bells, intelligent CCTV and other local safety infrastructure.","Improve alley lighting to support safer journeys home."],"change":"Aim to reduce anxiety during school commutes and late-night travel. Residents also need to know where facilities are and how to use them.","pages":"p. 4"},{"purpose":"Help residents experiencing loneliness meet others locally and rebuild everyday relationships.","measures":["Expand Seoul community well-being hubs to all districts.","Offer programs tailored to different age groups.","Provide shared dining and social opportunities for residents living alone."],"change":"Create accessible places to visit and talk. The key is whether a first encounter develops into a sustained relationship.","pages":"p. 4"},{"purpose":"Use in-person coaching to support learning continuity and questions that online learning alone cannot resolve.","measures":["Pilot at 10 community child centers before planned expansion to youth and lifelong learning facilities.","Provide tailored group mentoring for elementary-school students through Seoul Learn teachers.","The press release proposes expanding income eligibility from 80% to 100% of median income."],"change":"Children gain opportunities to ask questions and build study habits, while caregivers receive learning support. Access and travel to centers also need consideration.","pages":"p. 5"},{"purpose":"Reduce delays at each redevelopment stage to make housing supply more predictable.","measures":["Target construction starts for 310,000 homes by 2031.","Apply standard processing deadlines in priority redevelopment areas and use progress meetings to resolve bottlenecks.","Pursue faster association formation through a redevelopment fast-track for sites with more than 75% consent to form a steering committee."],"change":"Help residents understand progress and plan their housing needs. Construction starts are different from completed homes, and actual schedules must be checked for each site.","pages":"p. 6"},{"purpose":"Expand housing support across life stages and reduce risks before and after jeonse rental contracts.","measures":["Expand housing support for young people, newlyweds, older residents and other life stages.","Support pre-contract risk analysis.","Connect signing-day assistance from a housing support manager with post-contract deposit-return guarantee fee support."],"change":"Reduce the burden of judging complex information when signing a first contract. Support does not guarantee every contract is safe; eligibility and procedures require verification.","pages":"p. 6"},{"purpose":"Help young people build AI skills and work experience to widen employment and entrepreneurship opportunities.","measures":["Plan AI access vouchers and free basic training for 500,000 young people regardless of income.","Connect AI education with work experience and specialist training.","Link education, jobs and housing policies to support independent living."],"change":"Lower paid-tool costs and create opportunities to apply learning in real work. Project experience and job skills matter beyond access to tools alone.","pages":"p. 7"},{"purpose":"Connect nighttime activity with culture, tourism and local business while improving transport and safety.","measures":["Extend sports and cultural facility hours and expand nighttime experiences at the Han River, Namsan and DDP.","Plan district expansion following a pilot of moonlight outdoor dining areas.","Expand late-night buses and CCTV to support nighttime activities."],"change":"Offer residents and visitors more reasons to stay and enjoy the city at night. Consider travel home, nearby residents and operating conditions alongside commercial activity.","pages":"pp. 7–8"},{"purpose":"Distribute housing, jobs, learning and culture across Seoul so opportunities are closer to home.","measures":["Develop Youth Future Towns combining homes, jobs and community spaces on available sites, including rail depots.","Develop four urban hubs: Sangam–Susaek, Gasan–Guro, Changdong–Sanggye and Godeok–Gangil.","Connect local industry, universities and startup ecosystems, and create walkable neighborhood centers."],"change":"Aim to reduce distances between home, work and learning. New hubs need real jobs, local services and transport connections.","pages":"pp. 8–9"},{"purpose":"Apply autonomous technology to public transport and reduce gaps in early-morning and late-night travel.","measures":["Target 500 autonomous buses by 2030.","Expand operating hours in stages beyond weekday late-night and early-morning services, subject to safety validation.","Gradually increase the share of autonomous city buses through testing and regulatory development."],"change":"May widen travel choices before the first regular service or late at night. Safety, actual routes, frequency and stop accessibility must be checked.","pages":"p. 9"}];
function policyExplanation(){const t=topics[state.topic],d=policyDetails[state.topic];return `<section class="policy-explanation panel" aria-labelledby="policy-detail-title"><span class="tag">${groups[t[1]][0]} · Selected policy</span><h3 id="policy-detail-title">${state.topic+1}. ${t[0]}</h3><p class="policy-purpose">${d.purpose}</p><div class="policy-detail-grid"><div><h4>Key measures</h4><ul>${d.measures.map(v=>`<li>${v}</li>`).join('')}</ul></div><div class="citizen-change"><h4>What could change for residents</h4><p>${d.change}</p></div></div></section>`;}
const groups=[["Health & Safety","Connect exercise, mental well-being, green spaces and everyday safety within local communities.","03–04"],["Inclusive Growth","Reduce loneliness and gaps in education and care, and make participation easier.","04–05"],["Housing Security","Connect housing supply, support across life stages and protection against rental fraud.","05–06"],["Opportunity & Vitality","Expand skills, work experience, culture and nighttime economic opportunities.","07–08"],["Urban Innovation","Connect housing, jobs, learning, culture and mobility close to home.","08–09"]];
const topics=[["Fitness within 10 Minutes of Home",0,"Jung Hyun-woo","42 · Two-person household · Office worker","Lives in Jungnang-gu. Has few places to exercise after work.","Limited sports facilities, competition for reservations and restricted opening hours","Exercise regularly close to home","Expand local exercise opportunities through Seoul fitness centers and Fun Stations in unused subway spaces."],["24-Hour Neighborhood Safety",0,"Lee Su-jin","29 · Lives alone · Nurse working shifts","Lives in a studio in Gwanak-gu and walks through alleys late at night.","Dark alleys, CCTV blind spots and difficulty accessing emergency reporting tools","Feel safe returning home late","Strengthen everyday safety infrastructure through Seoul emergency bells, intelligent CCTV and improved alley lighting."],["Loneliness-Free Seoul 2.0",1,"Park Jung-sook","68 · Lives alone · Retired","Lives alone in a rental apartment in Nowon-gu and has no one to talk to during the week.","Limited program information, eating alone and anxiety about joining activities","Find regular neighborhood gatherings and lasting connections","Support everyday well-being and social connections through Seoul community well-being hubs and shared meals for people living alone."],["Seoul Learn In-Person Coaching Centers",1,"Choi Min-seo","38 · Single-parent household · Care worker","Lives in Gangseo-gu and struggles to support an elementary-school child with online learning.","Disengagement from learning, no teacher to answer questions and distance to the center","Help the child build study habits without private tutoring","Extend Seoul Learn into in-person coaching to help elementary-school students keep learning and resolve questions."],["Fast-Track Integrated Planning 2.0",2,"Kang Tae-young","45 · Four-person household · Small business owner","Owns an older apartment in Seongbuk-gu. The redevelopment steering committee stage is taking longer than expected.","Permit delays, unpredictable schedules and limited information","Understand redevelopment progress and plan ahead","Reduce delays at each redevelopment stage, with a target of starting construction on 310,000 homes by 2031."],["Housing Support & Rental Fraud Prevention",2,"Yoon Seo-a","27 · Lives alone · Early-career employee at a small business","Preparing a first jeonse rental contract with a KRW 100 million deposit.","Difficulty identifying risky listings, complex procedures and guarantee fees","Sign a safe contract and protect the deposit","Connect pre-contract risk analysis, a housing support manager on signing day and assistance with deposit-return guarantee fees after signing."],["Youth AI Opportunity Ladder",3,"Han Ji-ho","24 · Soon-to-graduate student · Job seeker","Lives in Dongdaemun-gu and wants to apply for jobs requiring AI skills.","Paid tool costs, limited work experience and scattered information","Build AI skills and work experience to find a first job","Connect AI access vouchers and basic training with work experience and specialist education to support youth employment and entrepreneurship."],["24-Hour Urban Vitality",3,"Oh Se-ra","35 · Two-person household · Shop owner near the Han River","Nighttime visitors are increasing, but conditions for late-night business remain limited.","Limited late-night transport, few nighttime activities and safety concerns","Connect nighttime visitors with local businesses","Expand nighttime experiences, access to cultural and sports facilities, late-night transport and safety infrastructure together."],["Youth Future Towns & Four Urban Hubs",4,"Jung Da-in","31 · Lives alone · Startup developer","Lives in Dobong-gu and has a long commute to an office in Gangnam.","Long commutes and limited local jobs and community networks","Work and learn closer to home","Expand local access to jobs, learning and housing through Youth Future Towns and a city with multiple urban centers."],["Expanding Autonomous Bus Services",4,"Lim Kyung-ho","57 · Three-person household · Early-shift sanitation worker","Lives in Eunpyeong-gu and has few travel options before the first regular bus.","Gaps before the first service, long waits and difficulty reaching bus stops","Commute reliably in the early morning","Target a fleet of 500 autonomous buses by 2030, with service expansion subject to safety validation."]];
const stages=[["I","Identify the Problem","Insight","Define the moment when a resident experiences a real difficulty in one sentence.","Who faces what difficulty, and where?"],["D","Explore Ideas","Divergence","Explore different solutions to the problem identified in your conversation.","Write down possible solutions and why they could help."],["E","Compare through Citizens’ Eyes","Empathy","Compare effectiveness, costs to residents and ease of use to choose solutions.","Which ideas and evaluation criteria matter most to you?"],["A","Build an Action Plan","Actionability","Specify partners, resources, obstacles and the first action.","Describe your selected idea, partners, resources and first step."]];
const initial={page:0,topic:0,step:0,drafts:{},format:'Visual story',audience:'Seoul residents learning about this policy for the first time',message:'',promoAnswer:'',application:'',policyQuestion:''};let state;try{state={...initial,...JSON.parse(localStorage.getItem('seoul-idea-en-v1')||'{}')}}catch{state={...initial}}if(!Number.isInteger(state.topic)||!topics[state.topic])state.topic=0;if(!Number.isInteger(state.page)||state.page<0||state.page>4)state.page=0;if(!Number.isInteger(state.step)||!stages[state.step])state.step=0;if(!state.drafts||typeof state.drafts!=='object')state.drafts={};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draft(){if(!state.drafts[state.topic]){const t=topics[state.topic];state.drafts[state.topic]={name:t[2],profile:t[3],daily:t[4],pain:t[5],wish:t[6],question:'When do you experience the greatest difficulty?',citizen:'',notes:['','','',''],answers:['','','',''],format:'Visual story',audience:'Seoul residents learning about this policy for the first time',message:'',promoAnswer:'',application:''}}return state.drafts[state.topic]}
function save(){try{localStorage.setItem('seoul-idea-en-v1',JSON.stringify(state));$('#save').textContent='Saved in this browser'}catch{$('#save').textContent='Unable to save — copy your work to keep it'}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function go(p){state.page=p;save();render();window.scrollTo({top:0,behavior:'smooth'})}
function choose(n){state.topic=Number(n);save();render()}
function field(label,key,value,multi=false,placeholder=''){return `<label for="${key}">${label}</label><${multi?'textarea':'input'} id="${key}" data-field="${key}" placeholder="${esc(placeholder)}" ${multi?'':`value="${esc(value)}"`}>${multi?esc(value)+'</textarea>':''}`}
function selector(){return `<label for="topic">Workshop topic</label><select id="topic">${topics.map((t,i)=>`<option value="${i}" ${i===state.topic?'selected':''}>${i+1}. ${t[0]}</option>`).join('')}</select>`}
function context(){const t=topics[state.topic],d=draft();return `Workshop group: ${state.topic+1}\nPolicy: ${t[0]}\nPolicy area: ${groups[t[1]][0]}\nPolicy reference: ${t[7]}\nResident: ${d.name}, ${d.profile}\nDaily situation: ${d.daily}\nDifficulties: ${d.pain}\nDesired change: ${d.wish}`}
function cardNewsPrompt() {
  const d = draft();
  return `${mediaBrief()}

[CREATE THE IMAGE NOW]
Use the image generation tool to directly create an English six-panel visual story. The requested deliverable is an actual generated image, not a plan, copy list or production instructions.
Selected design style: ${d.creativeStyle || stylesFor('Visual story')[0]}
Internally plan six connected panels and a shared design. Do not output drafts first. Generate exactly ONE flat landscape image with six equal square panels in a 3-column × 2-row grid. Aim for 3240 × 2160 pixels, or the nearest supported high-resolution landscape size. Reading order: 1–3 across the top row, then 4–6 across the bottom. Use consistent gutters and outer margins. Include all six panels in one result without requiring further input.

[SIX-PANEL STORY]
1. Cover: a short title, policy name and key visual showing the main benefit.
2. A relevant everyday situation. No exaggerated difficulties or fabricated testimonials.
3. The core service supported by the supplied material.
4. A concrete moment of service use. Do not invent application procedures.
5. Expected improvements in daily life. Do not present expectations as achieved results.
6. A memorable closing message. Do not invent application information.

[DESIGN RULES]
Each panel should be a complete scene in a sequential story, not a tilted mockup or a collection of design alternatives. Include actual illustrations, photographic scenes or visual elements in the selected style, alongside English text. Avoid text-only sheets.
Limit each panel to one short headline and one concise body sentence. Place the text directly inside the image. Use large, legible English type, high contrast and generous margins; check spelling, clipping and overlap. Keep colors, typography, spacing, illustration style and recurring characters consistent. Add small panel numbers 1/6–6/6. Do not include workshop group numbers or production instructions.
Keep policy facts intact. Do not invent figures, outcomes, schedules, eligibility, testimonials, contacts, application links, QR codes or official logos. Clearly distinguish proposals and plans from confirmed services.

[FINAL OUTPUT]
Show the generated image first. Do not substitute a Markdown table, code block, HTML/SVG, image-generation prompt or instructions. Do not claim an image was created by merely providing a filename or link. If actual image generation is unavailable, state that limitation briefly and do not claim completion.`;
}
function prompt() {
  const d = draft(), t = topics[state.topic];
  const rule = 'Base the response on the supplied policy description. Distinguish targets from achieved results. Do not invent figures, budgets or eligibility rules. Label new ideas as proposals and list points requiring verification. Write concise English throughout, including text inside images. Translate user-provided material faithfully when needed.';
  if (state.page === 0) return `${rule}\nThe five visions of the G3 Seoul Plan are:\n${groups.map(g => g[0] + ': ' + g[1]).join('\n')}\nQuestion: ${state.policyQuestion || 'Explain how each vision could change everyday life, with examples and three questions to check understanding.'}`;
  if (state.page === 1) return `${rule}
${context()}
Respond as this fictional resident. Do not present the response as actual citizen research; label unspecified details as assumptions.
My question: ${d.question}
Organize the questions and answer each from the resident’s point of view. Clearly separate questions and answers.

[REQUIRED IMAGE DELIVERABLES]
After the questions and answers, actually use image generation to create and show TWO separate images: one citizen persona board and one service journey map. Do not substitute design advice, generation prompts, Markdown tables or code. Use the supplied scenario and answers without asking for more input or production approval.

[1. CITIZEN PERSONA BOARD]
Create one high-resolution landscape persona board. On the left, place a friendly illustration matching the resident’s age, occupation and living circumstances, with an everyday Seoul setting. On the right, include concise English text: name, age, household, occupation, daily situation, main difficulties, desired change, policy touchpoints and a first-person quote. Make a filled-in persona board, not only a portrait. Treat unspecified gender or appearance as illustrative assumptions. Do not use stereotypes to infer personality or needs.

[2. CITIZEN JOURNEY MAP]
Create one high-resolution landscape image showing the same resident before, during and after service use. Default stages: Need arises → Seek information → Access or apply → Use service → Changes afterward. Adapt to 6–7 stages if appropriate. For services without applications, use suitable visiting, travel or participation stages. Do not invent actual procedures or features.
Put stages in chronological order across the horizontal axis. Rows: goals; actions; touchpoints (people, places, channels); thoughts and questions; emotions; difficulties and barriers; improvement opportunities. Fill every cell with specific details from this scenario, using keywords or one short sentence. Write thoughts in the first person. Show emotions with words and emoji, and connect their progression with a line. These are fictional emotions, not measured research scores. Highlight 1–2 moments of greatest difficulty and where policy services could help. Use the same character, colors and visual style as the persona board.

[QUALITY FOR BOTH IMAGES]
Use bright, orderly infographics, large English text, high contrast and generous spacing. Place text directly in each image and check spelling, clipping and overlap. Shorten wording if needed without losing the structure. Add a small “Fictional citizen scenario” label to each image, and label additional inferences “Assumption” or “Verification needed”. Do not imply these are actual research findings.
After showing both images, briefly identify two priority improvements and two questions for real residents. Retain this context for the IDEA exercise in the same conversation.
If only one image can be generated per response, generate the persona board first, then the journey map with the same citizen settings when the user says “Continue”. If image generation is unavailable, state the limitation briefly; do not claim to have generated images or pass off text tables as image outputs.

[FINAL SUMMARY]
Summarize the key findings from the questions, answers, persona and journey map in exactly three lines.`;
  if (state.page === 2) {
    const tasks = [
      'Separate the difficulty, its causes and its effects before proposing solutions. Define the core problem in one sentence and provide three verification questions.',
      'Start with the previously defined problem and improvement opportunities in the journey map. Incorporate additional ideas if provided. Offer five solutions with distinct approaches. Give each a name and summarize its mechanism, benefit and difference from the existing policy in one line. Then provide up to three directly relevant international examples, identifying country or city, initiative, core approach, a lesson for Seoul and the related idea number. Where possible, search and verify official sources and include one source link per example. If searching is unavailable, use only examples you can support and flag unverified details. Do not invent initiative names, results or URLs. If fewer than three examples can be verified, provide only those. Output only two groups: five idea lines and up to three example lines. Keep each item under 40 words excluding its URL and the full response under 320 words. Omit introductions, background essays and conclusions.',
      'Compare the earlier ideas by effectiveness, cost to residents and ease of use. Explain the basis of each assessment and label assumptions. Select two or three options, identify residents who might be excluded and suggest mitigations.',
      'Turn the selected idea into a proposed action plan. Include responsible and collaborating parties (to be verified), resources, implementation sequence, obstacles, responses, resident-centered success measures and the first action. Do not present it as an approved plan. End with “Policy Content and Key Message for Promotion”. Describe the intended residents, service and expected change in two or three sentences, followed by one short, accessible key message. Keep it consistent with the selected plan, and do not present proposals as confirmed policies or results.'
    ];
    return `Continue the current IDEA stage in the SAME Gemini workshop conversation. Use the selected policy, citizen questions and answers, journey map and previous IDEA results already in the conversation. Do not ask the user to paste prior answers or conversation records again.
${rule}
Selected topic: Group ${state.topic + 1}. ${t[0]}
Current stage: ${stages[state.step][2]} / ${stages[state.step][1]}
Prioritize the latest revisions and choices for this topic. Do not mix in results for other topics. If no additional thoughts are supplied, proceed using the existing conversation. If earlier context is actually absent, do not pretend to have seen it; provide a draft with the minimum necessary assumptions clearly identified.
${d.notes[state.step].trim() ? 'Additional thoughts for this stage: ' + d.notes[state.step].trim() + '\n' : ''}Task: ${tasks[state.step]}`;
  }
  if (state.page === 3) {
    if (d.format === 'Visual story') return cardNewsPrompt();
    if (d.format === 'Promotional video') return videoPrompt();
    if (d.format === 'Promotional song') return musicPrompt();
    const requirements = {
      'Promotional poster': 'Actually use image generation to create ONE high-resolution comparison image containing SIX distinct poster concepts for the same policy and key message. Do not provide only a description or generation prompt. Divide a landscape canvas into a 3-column × 2-row grid of equal panels, each containing one portrait poster design. Keep margins and sizes consistent; prevent clipping or overlap. Label each panel 01–06 with a short English concept title. Use the selected style as a starting point, but differentiate: 1) bold typography, 2) everyday citizen scenes, 3) symbolic objects, 4) narrative composition, 5) visualized key information, 6) bold colors and shapes. Vary composition, information placement, headline treatment and main visual elements, not just color. Keep policy facts and the key message consistent. Put a readable English headline and short benefit statement directly inside each poster. Use large type and generous space. Do not invent figures, outcomes, application methods, contacts, QR codes or logos. Show the comparison image first, then explain each concept in one sentence. If image generation is unavailable, state this clearly and do not claim an image was created.',
      'Promotional webpage': 'Create a responsive single-file HTML webpage that can be previewed in Gemini Canvas. Include HTML, CSS and JavaScript together. Use accessible buttons, large readable text and English copy, with lang="en". Do not imply an unconnected application feature works.'
    };
    return `${mediaBrief()}\nFormat: ${d.format}\nVisual style: ${d.creativeStyle || stylesFor(d.format)[0]}\n${requirements[d.format]}\nDo not invent actual availability, application links or contact details.`;
  }
  return `${rule}\n${context()}\nLearning notes:\n${d.answers.join('\n')}\nPrepare a one-page policy improvement proposal covering the citizen’s problem, improvement idea, selection rationale, implementation conditions and first action. Do not fill missing information with invented facts; ask targeted follow-up questions.`;
}

function preview(){return `<section class="panel preview"><span class="tag">GEMINI PROMPT BUILDER</span><h3>Your ready-to-use prompt</h3><label for="prompt" class="small">Updates automatically as you enter information. You can also edit it directly.</label><textarea id="prompt">${esc(prompt())}</textarea><div class="actions"><button class="primary" id="copy">Copy prompt</button>${state.page===2?'':'<a class="secondary button-link" href="https://gemini.google.com/app" target="_blank" rel="noopener noreferrer">Open Gemini ↗</a>'}${state.page===3&&draft().format==='Promotional song'?'<a class="secondary button-link" href="https://www.flowmusic.app/" target="_blank" rel="noopener noreferrer">Open Flow Music ↗</a>':state.page===3&&draft().format==='Promotional video'?'<a class="secondary button-link" href="https://flow.google.com/" target="_blank" rel="noopener noreferrer">Open Flow ↗</a>':''}</div><p class="small">${state.page===2?'Copy this prompt into your existing Gemini workshop conversation to continue. There is no need to re-enter the citizen conversation or previous results.':'Copy the prompt, open Gemini and paste it into the chat. Sign in there. You can save the response in the notes below.'}</p></section>`}
function response(label,key,value){return `<section class="panel answer">${field(label,key,value,true,'Paste a Gemini response or your own summary.')}<p class="small">Review the key points and refine them in your own words.</p></section>`}
function render(){state.page=/\/promotion(?:\.html)?\/?$/.test(location.pathname)?3:2;const promo=state.page===3;document.title=promo?'Create Content · G3 Seoul Plan':'G3 Seoul Plan';$('#nav').innerHTML=`<a href="/explore.html" class="route-card ${!promo?'active':''}" ${!promo?'aria-current="page"':''}><span>01 · Explore Policies</span><strong>Explore policies through citizens’ eyes ↗</strong><small>Understand · Meet residents · Practice IDEA</small></a><a href="/promotion.html" class="route-card ${promo?'active':''}" ${promo?'aria-current="page"':''}><span>02 · Create Content</span><strong>Create policy content in your style ↗</strong><small>Images · Music · Video · Webpages</small></a>`;$('#crumb').textContent=promo?'G3 Seoul Plan / Create Content':'G3 Seoul Plan / Explore Policies';const d=draft(),t=topics[state.topic],s=stages[state.step];let html='';
if(!promo)html=`<h2>Explore Seoul’s policies.<br><em>Improve everyday life.</em></h2><p class="intro">Choose a policy and see it through a resident’s eyes. Continue into the IDEA exercise on this page.</p><section id="policies" class="learning-section"><div class="section-heading"><span>01</span><h3>Understand the Policy</h3></div><div class="policy-grid">${groups.map((g,i)=>`<section class="card"><span class="tag">Five visions for Seoul</span><h3>${g[0]}</h3><p>${g[1]}</p><div class="policy-row">${topics.map((t,j)=>t[1]===i?`<button data-topic="${j}" class="${j===state.topic?'selected':''}" aria-pressed="${j===state.topic}">${j+1}. ${t[0]}</button>`:'').join('')}</div></section>`).join('')}</div>${policyExplanation()}</section><section id="citizen-section" class="learning-section"><div class="section-heading"><span>02</span><h3>Meet a Resident</h3></div><div class="panel citizen-policy-picker"><label for="topic">Choose a policy to explore from a resident’s perspective</label><select id="topic">${topics.map((item,i)=>`<option value="${i}" ${i===state.topic?'selected':''}>${i+1}. ${item[0]}</option>`).join('')}</select><p class="small">Loads a citizen scenario for your selected policy. The policy description above and IDEA exercise below use the same selection.</p></div><div class="workspace"><section class="panel"><div class="form-pair"><div>${field('Resident’s name','name',d.name)}</div><div>${field('Age · Household · Occupation','profile',d.profile)}</div></div>${field('Home and daily situation','daily',d.daily,true)}${field('Main difficulties','pain',d.pain,true)}${field('Most desired change','wish',d.wish)}${field('Question for the resident','question',d.question,true)}</section><section class="panel preview"><span class="tag">Ask from a resident’s perspective</span>${extraPreview(1,'citizen-prompt')}${field('Insights from the conversation (optional notes)','citizen',d.citizen,true,'Take notes if helpful. You do not need to enter them again for the IDEA exercise.')}</section></div></section><section id="idea-section" class="learning-section"><div class="section-heading"><span>03</span><h3>IDEA Workshop</h3></div><p class="small">Copy each stage prompt into the same Gemini conversation used to meet the resident. No extra writing is required.</p><div class="step-tabs">${stages.map((x,i)=>`<button data-step="${i}" class="${state.step===i?'active':''}" aria-pressed="${state.step===i}">${x[0]} · ${x[1]}</button>`).join('')}</div><div class="workspace"><section class="panel"><span class="tag">${s[2]}</span><h3>${s[1]}</h3><p>${s[3]}</p><div class="thought-actions"><button type="button" class="secondary" id="insert-example">💡 Insert an example</button><button type="button" class="secondary" id="clear-example">Remove example</button><span class="small">Insert an example and adapt it to your own ideas.</span></div>${field('Add your thoughts (optional)','note',d.notes[state.step],true,s[4])}</section>${preview()}</div>${response(s[0]+' stage results (optional notes)','answer',d.answers[state.step])}<p class="small">These are personal notes. Even if left blank, Gemini can use earlier results in the same conversation.</p><div class="actions">${state.step>0?`<button class="secondary" data-step="${state.step-1}">← Previous stage</button>`:''}${state.step<3?`<button class="primary" data-step="${state.step+1}">Next stage →</button>`:'<a class="primary button-link" href="/promotion.html">Create promotional content →</a>'}</div></section><p class="source">Learning references: 2026 Seoul Creative Administration Workshop slides 1–14; G3 Seoul Plan press release (September 10, 2026), pp. 2–9. Policy descriptions include targets and plans.</p>`;
else html=`<h2>Bring policy benefits<br><em>to the people.</em></h2><p class="intro">Choose a policy, content format and style to build your own production prompt.</p><div class="media-options">${[['Promotional poster','Images','Posters · Visual stories'],['Promotional song','Music','Dance pop · Choir · Korean fusion'],['Promotional video','Video','Rhythmic · Cinematic'],['Promotional webpage','Webpages','Information · Campaigns']].map(([f,n,h])=>`<button data-format="${f}" class="${d.format===f||f==='Promotional poster'&&d.format==='Visual story'?'selected':''}"><strong>${n}</strong><small>${h}</small></button>`).join('')}</div><div class="workspace"><section class="panel">${selector()}<div class="hint">${t[7]}</div><label for="format">Content format</label><select id="format">${['Visual story','Promotional poster','Promotional song','Promotional video','Promotional webpage'].map(x=>`<option ${x===d.format?'selected':''}>${x}</option>`).join('')}</select><label for="creativeStyle">${d.format==='Promotional song'?'Song genre':d.format==='Promotional video'?'Video direction':'Visual style'}</label><select id="creativeStyle">${stylesFor(d.format).map(x=>`<option ${x===d.creativeStyle?'selected':''}>${x}</option>`).join('')}</select>${d.format==='Promotional video'?videoFields():d.format==='Promotional song'?'<div class="hint">About 2 minutes · Requests complete lyrics and music settings in a single code block.</div>':''}${field('Who is your audience?','audience',d.audience)}${field('Policy content and key message','promoContent',promotionContent(d),true,'Describe the policy or proposed improvement, benefits for residents and the key message.')}<p class="small">You can start here without completing policy exploration first.</p></section>${preview()}</div><div class="hint">Gemini media features may vary by account. Posters request six design concepts in one image; visual stories request six panels in a 3 × 2 image. Video prompts request three standalone 10-second videos with distinct concepts. Songs request lyrics and music settings. Webpages are designed for Gemini Canvas.</div>${response('Content production notes','promoAnswer',d.promoAnswer)}`;
$('#content').innerHTML=html;bind();}
function stylesFor(format){return format==='Promotional song'?['Dance pop','Pop','Choir','Korean traditional fusion','Acoustic']:format==='Promotional video'?['Rhythmic ad','Cinematic','Vlog','Documentary','Animation']:format==='Promotional webpage'?['Information guide','Campaign','Storytelling']:['Clean civic design','Photorealistic','Watercolor','3D illustration','Comic'];}
function phasePrompt(phase){const before=state.page;state.page=phase;const text=prompt();state.page=before;return text;}
function extraPreview(phase,id){return `<label for="${id}">Ready-to-use prompt</label><textarea id="${id}" class="extra-prompt">${esc(phasePrompt(phase))}</textarea><div class="actions"><button class="primary" data-copy="${id}">Copy prompt</button><a class="secondary button-link" href="https://gemini.google.com/app" target="_blank" rel="noopener noreferrer">Open Gemini ↗</a></div><p class="small">Copy the prompt, open Gemini and paste it into the chat.</p>`;}
async function copyPrompt(open,id='prompt'){const p=$('#'+id);const value=p.value;let success=false;try{await navigator.clipboard.writeText(value);success=true}catch{p.focus();p.select();try{success=document.execCommand('copy')}catch{}}if(success)toast(open?'Copied. Paste it into Gemini.':'Prompt copied.');else toast('Automatic copying is unavailable. Copy the selected prompt manually.');return success}
const ideaExampleOptions=[["Show exercise spaces and opening hours along the commute home","Offer short exercise sessions without reservations"],["Review dark stretches of the route home with residents","Explain emergency bell locations and how to use them"],["Welcome first-time visitors with a companion guide","Connect small neighborhood dining groups"],["Explain center travel routes and times to caregivers","Carry online questions into in-person coaching"],["Explain project stages and next steps clearly","Collect and answer residents’ questions regularly"],["Create a one-page checklist of documents to review before signing","Connect pre-contract advice with signing-day assistance"],["Follow basic training with a small practical project","Bring role-specific AI learning paths into one place"],["Connect nighttime events with nearby shop information","Bring travel-home and safety information together"],["Connect residents to nearby jobs and learning spaces","Organize small collaboration groups for local businesses and young people"],["Assess bus stop demand along early-morning commute routes","Explain service hours and waiting times clearly"]];
function thoughtExample(){const d=draft(),opts=ideaExampleOptions[state.topic];return [
  d.name+' experiences difficulty because of '+d.pain+'. I want to identify the most difficult moment first, to help achieve this goal: '+d.wish+'.',
  'I would like to propose “'+opts[0]+'” and “'+opts[1]+'”. I will first consider how to make them easy for residents to use.',
  'I want to compare the ideas by how they reduce difficulties, costs to residents and barriers to access. I will prioritize options that are easy to use.',
  'I want to pilot the selected idea on a small scale. I will check potential partners, listen to residents, and identify resources and a first action.'
][state.step];}
function insertThoughtExample(){const el=$('#note'),example=thoughtExample();if(el.value.includes(example)){toast('This example is already included. Adapt it to your own ideas.');return;}const d=draft();d.insertedExamples??={};d.insertedExamples[state.step]=example;el.value=el.value.trim()?el.value+'\n\n[Example]\n'+example:example;el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();toast('Example inserted. Adapt it to your own ideas.');}
function clearThoughtExample(){const el=$('#note'),d=draft(),example=d.insertedExamples?.[state.step]||thoughtExample();if(!el.value.includes(example)){toast('The original example was not found. Remove edited text manually.');return;}const marked='\n\n[Example]\n'+example;el.value=el.value.includes(marked)?el.value.replace(marked,''):el.value.replace(example,'');if(d.insertedExamples)delete d.insertedExamples[state.step];el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();toast('Example removed.');}
function bind(){if($('#clear-example'))$('#clear-example').onclick=clearThoughtExample;if($('#insert-example'))$('#insert-example').onclick=insertThoughtExample;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(Number(b.dataset.page)));document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>choose(b.dataset.topic));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.step);save();render();$('#idea-section')?.scrollIntoView({block:'start'})});if($('#topic'))$('#topic').onchange=e=>{const y=window.scrollY;choose(e.target.value,state.page);window.scrollTo({top:y,behavior:'instant'});$('#topic')?.focus({preventScroll:true})};if($('#format'))$('#format').onchange=e=>{draft().format=e.target.value;draft().creativeStyle=stylesFor(e.target.value)[0];save();render()};if($('#creativeStyle'))$('#creativeStyle').onchange=e=>{draft().creativeStyle=e.target.value;save();$('#prompt').value=prompt()};document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{draft().format=b.dataset.format;draft().creativeStyle=stylesFor(draft().format)[0];save();render()});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyPrompt(false,b.dataset.copy));document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{const k=el.dataset.field,d=draft();if(k==='note')d.notes[state.step]=el.value;else if(k==='answer')d.answers[state.step]=el.value;else if(k==='policyQuestion')state[k]=el.value;else d[k]=el.value;save();if($('#prompt'))$('#prompt').value=prompt();if($('#policy-prompt'))$('#policy-prompt').value=phasePrompt(0);if($('#citizen-prompt'))$('#citizen-prompt').value=phasePrompt(1);if($('#application-view'))$('#application-view').textContent=draft().application});if($('#copy'))$('#copy').onclick=()=>copyPrompt(false);}
draft();render();save();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_learning_prompt',description:'Reads the current Gemini learning prompt without transmitting it externally.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({topic:topics[state.topic][0],page:state.page,prompt:$('#prompt')?.value||prompt()})})).catch(()=>{})}catch{}}
